# price(): 10 percent off gold, 5 off orders over 100
def order(c, p, q):
    return {"c": c, "items": [{"p": p, "q": q}]}

def test_pins_current_behavior():
    assert price(order("gold", 60, 2)) == 103.0
    assert price(order("none", 60, 2)) == 115.0
    assert price(order("none", 50, 2)) == 100.0
